function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const LT = colLetter(cT), LP = colLetter(cP), LN = colLetter(cN), LA = colLetter(cA);

// ---- meetings: latest staircase block ----
function isHdr(row) { return /startup got meetings/i.test(s((row || [])[1])) && /\d/.test(s((row || [])[0])); }
const hdrs = []; for (let i = 0; i < grid.length; i++) { if (isHdr(grid[i])) { hdrs.push(i); } }
