const TODAYD = new Date(Date.UTC(2026, 8, 11));
function blockDate(label) { const m = s(label).match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/); if (!m) { return null; }
  const a = +m[1], b = +m[2], y = +m[3]; const c = [];
