  if (!h.length) { return null; }
  return { lo: Math.min.apply(null, h), hi: Math.max.apply(null, h), seed: h.indexOf(1) >= 0 }; }
function chequeMin(txt) { const t = s(txt).replace(/,/g, '').toLowerCase(); if (!t) { return null; }
  const usd = /\$|usd/.test(t); const re = /(\d+(?:\.\d+)?)\s*(crores?|cr|million|mn|m|k|lakhs?|lacs?)?(?![a-z])/g;
  const tok = []; let m; while ((m = re.exec(t)) !== null) { tok.push({ v: parseFloat(m[1]), u: m[2] || '' }); }
