  return null; }
const FLOOR_FIX = { a2dventures: 0.85, mintvc: 0.5, pipersireca: 1.0 };
const byName = {};
for (const r of invRaw) { const n = s(r.investor); if (!n) { continue; } const k = nz(n); if (!byName[k]) { byName[k] = []; } byName[k].push(r); }
const inv = {};
for (const k of Object.keys(byName)) { const rs = byName[k]; const pick = rs.filter(function (r) { return s(r.stage) !== ''; })[0] || rs[0];
  let floor = chequeMin(pick.cheque_inr_cr); if (FLOOR_FIX[k] !== undefined) { floor = FLOOR_FIX[k]; }
  inv[k] = { dnc: rs.some(function (r) { return s(r.do_not_contact).toLowerCase() === 'yes'; }), agnostic: /agno/i.test(s(pick.sector)), tags: tagsOf(pick.sector), band: investorBand(pick.stage), floor: floor }; }
