  type_counts: counts, drops: drops.length, drop_reasons: dropWhy, new_holds: holds.length,
  drop_list: drops.map(function (d) { return [d.rn, d.deal, d.st, d.inv, d.t]; }), old_priority_backup: oldBackup, data: data } }];

